'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultSongs=[{id:'s1',title:'Horizonte aberto',artist:'Composição de exemplo',key:'Em',bpm:90,status:'Estudando',notes:'Progressão: Em • C • G • D\n\nIdeia de estudo: toque cada acorde por um compasso. Comece em 70 BPM e aumente quando estiver confortável.'},{id:'s2',title:'Blues da madrugada',artist:'Exercício de exemplo',key:'A',bpm:80,status:'Pronta',notes:'Blues de 12 compassos em A:\nA7 | A7 | A7 | A7\nD7 | D7 | A7 | A7\nE7 | D7 | A7 | E7\n\nExperimente improvisar com a pentatônica menor de A.'},{id:'s3',title:'Entre acordes',artist:'Ideia de exemplo',key:'C',bpm:105,status:'Ideia',notes:'C • Am • F • G\n\nAnote aqui os detalhes do arranjo.'}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem('palco-'+key))??fallback;}catch{return fallback;}}
let songs=read('songs',defaultSongs), ideas=read('ideas',[]), history=read('history',[]), checked=read('checks',{}), page='inicio';
let storageWarned=false;function save(){try{localStorage.setItem('palco-songs',JSON.stringify(songs));localStorage.setItem('palco-ideas',JSON.stringify(ideas));localStorage.setItem('palco-history',JSON.stringify(history));localStorage.setItem('palco-checks',JSON.stringify(checked));}catch{if(!storageWarned){storageWarned=true;toast('O navegador não permitiu salvar. Mantenha esta página aberta.');}}}
const tasks=[{title:'Aquecimento & independência',subtitle:'Cromatismo 1–2–3–4',minutes:5},{title:'Técnica & precisão',subtitle:'Palhetada alternada',minutes:10},{title:'Repertório & criatividade',subtitle:'Pratique uma música sua',minutes:15}];
const today=()=>new Date().toLocaleDateString('pt-BR');
const done=i=>!!checked[today()+'-'+i];
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').style.display='none',3500);}
function songRows(list){return list.length?list.map((s,i)=>`<button class="song" data-song="${esc(s.id)}"><span class="cover ${['','two','three'][i%3]}">${s.status==='Ideia'?'✧':'♫'}</span><span><span class="songtitle">${esc(s.title)}</span><span class="subtext">${esc(s.artist||'Sem artista')} • ${esc(s.key)}</span></span><span class="songmeta">${esc(s.bpm)} BPM</span><span class="pill ${s.status==='Pronta'?'ready':''}">${esc(s.status)}</span><span class="arrow">↗</span></button>`).join(''):'<div class="empty">Nenhuma música aqui ainda. Adicione a primeira.</div>';}
function head(eyebrow,title,description,action=''){return `<div class="pageheading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="subtext">${description}</p></div>${action}</div>`;}
function sessionRows(){return tasks.map((t,i)=>`<div class="sessionrow"><button class="check ${done(i)?'done':''}" data-check="${i}" aria-label="${done(i)?'Desmarcar':'Concluir'} ${t.title}" aria-pressed="${done(i)}">${done(i)?'✓':''}</button><div>${t.title}<small>${t.subtitle}</small></div><span>${t.minutes} min</span></div>`).join('');}
function dashboard(){const total=history.reduce((a,h)=>a+h.minutes,0),week=history.filter(h=>Date.now()-h.timestamp<604800000),n=tasks.filter((_,i)=>done(i)).length;return head('TODO DIA É DIA DE TOCAR.','Boa música começa <em>com você.</em>','Bem-vindo, Ivan. O seu próximo passo está aqui.','<button class="primary" data-add>+ Adicionar música</button>')+`<section class="hero"><div><span class="eyebrow">MENOS DISTRAÇÃO. MAIS MÚSICA.</span><h2>Encontre seu ritmo.<br>Faça o som acontecer.</h2><p>Seu repertório, seus estudos e suas ideias.<br>Tudo junto, para você se dedicar ao que importa.</p><button class="primary" data-page="estudos">Começar meu treino <span>↗</span></button></div><div class="heroart approved-art"><img src="assets/ensaio-logo-aprovada.png" alt="ënsaio — identidade musical"><span class="identity-caption">SEU SOM COMEÇA NO ENSAIO.</span></div></section><section class="stats"><div class="stat"><div class="statlabel">Tempo de prática <span>◷</span></div><div class="statvalue">${total}<sup> min</sup></div><small class="green">Cada sessão conta</small></div><div class="stat"><div class="statlabel">No repertório <span>♫</span></div><div class="statvalue">${songs.length.toString().padStart(2,'0')}</div><small>${songs.filter(s=>s.status==='Pronta').length} músicas prontas para tocar</small></div><div class="stat"><div class="statlabel">Sessões nesta semana <span>▥</span></div><div class="statvalue">${week.length.toString().padStart(2,'0')}</div><small>Construa sua constância</small></div><div class="stat"><div class="statlabel">Ideias registradas <span>✧</span></div><div class="statvalue">${ideas.length.toString().padStart(2,'0')}</div><small>Inspiração merece espaço</small></div></section><div class="dashboardgrid"><section><div class="sectionhead"><h2>Seu som, em construção</h2><button class="textbutton" data-page="repertorio">Ver repertório <span>↗</span></button></div><div class="songlist">${songRows(songs.slice(0,3))}</div></section><section><div class="sectionhead"><h2>Seu treino de hoje</h2><span class="eyebrow">30 MIN</span></div><div class="session"><div class="sessiontop"><span>Sessão essencial</span><span>${n}/3 concluídos</span></div>${sessionRows()}<div class="progressbar"><span style="width:${n/3*100}%"></span></div><button class="secondary wide" data-page="estudos">${n===3?'Revisar meu treino':'Abrir sessão'} <span>→</span></button></div></section></div><section class="tools"><div class="sectionhead"><h2>Na hora de tocar</h2><span class="subtext">Suas ferramentas, à mão.</span></div><div class="toolgrid"><button class="toolcard" data-page="metronomo"><span class="toolicon">♩</span><div><b>Metrônomo</b><small>Precisão no seu tempo</small></div><span class="arrow">↗</span></button><button class="toolcard" data-page="acordes"><span class="toolicon">▦</span><div><b>Biblioteca de acordes</b><small>Encontre novas possibilidades</small></div><span class="arrow">↗</span></button><button class="toolcard" data-page="ideias"><span class="toolicon">✧</span><div><b>Caderno de ideias</b><small>Não deixe aquele riff escapar</small></div><span class="arrow">↗</span></button></div></section>`;}
function repertoire(){return head('TOCAR & CRIAR','Meu repertório.','Um lugar para organizar tudo o que você quer tocar.','<button class="primary" data-add>+ Adicionar música</button>')+`<div class="filters"><input id="search" aria-label="Buscar música ou artista" placeholder="⌕  Buscar música ou artista…"><select id="filter" aria-label="Filtrar status"><option value="">Todos os status</option><option>Estudando</option><option>Pronta</option><option>Ideia</option></select></div><div class="songlist" id="results">${songRows(songs)}</div><div class="hint">As três músicas iniciais são exemplos. Cadastre suas próprias músicas, cifras e anotações. Seus registros são salvos neste navegador.</div>`;}
let bpm=90,metroTimer=null,audio=null,beatIndex=0,meter=4,subdivision=1;
function metronome(){return head('CAIXA DE FERRAMENTAS','No seu tempo.','Uma batida de cada vez. Treine com precisão.')+`<div class="metrolayout"><section class="panel metro"><span class="eyebrow">METRÔNOMO</span><div class="bpmvalue" id="bpmvalue">${bpm}</div><div class="bpmlabel">BATIDAS POR MINUTO</div><div class="beats" id="beats">${Array.from({length:meter},(_,i)=>`<span class="beat" data-beat="${i}"></span>`).join('')}</div><div class="stepper"><button data-bpm="-5" aria-label="Diminuir 5 BPM">−</button><input id="bpmnumber" type="number" min="30" max="240" value="${bpm}" aria-label="BPM"><button data-bpm="5" aria-label="Aumentar 5 BPM">+</button></div><input id="bpmrange" type="range" min="30" max="240" value="${bpm}" aria-label="Ajustar andamento"><button class="primary bigplay" id="metroplay">▶ Iniciar metrônomo</button><button class="textbutton" style="margin:18px auto 0" id="tap">Tap tempo • clique no ritmo</button></section><section class="panel"><h2>Prepare sua prática</h2><p class="subtext" style="margin-top:10px">Escolha o andamento e acompanhe o pulso.</p><label>Compasso<select id="meter"><option value="4">4/4 • quatro tempos</option><option value="3">3/4 • três tempos</option><option value="6">6/8 • seis pulsos</option></select></label><label>Subdivisão<select id="subdivision"><option value="1">Um clique por pulso</option><option value="2">Dois cliques por pulso</option><option value="4">Quatro cliques por pulso</option></select></label><div class="hint"><span class="green">COMECE DEVAGAR</span><br>Escolha um trecho curto. Toque sem tensão e aumente 5 BPM quando conseguir repetir com clareza.</div><div class="hint">Ative o som do aparelho para ouvir os cliques. No iPhone, mantenha esta página aberta durante a prática.</div></section></div>`;}
function clickSound(accent){const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=accent?1400:850;g.gain.setValueAtTime(.17,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.045);o.start();o.stop(audio.currentTime+.05);}
function stopMetro(){clearInterval(metroTimer);metroTimer=null;beatIndex=0;$$('.beat').forEach(b=>b.classList.remove('lit'));if($('#metroplay'))$('#metroplay').textContent='▶ Iniciar metrônomo';}
function startMetro(){stopMetro();const tick=()=>{const main=beatIndex%subdivision===0;if(main){$$('.beat').forEach((b,i)=>b.classList.toggle('lit',i===Math.floor(beatIndex/subdivision)%meter));}clickSound(beatIndex%(meter*subdivision)===0);beatIndex++;};tick();metroTimer=setInterval(tick,60000/bpm/subdivision);$('#metroplay').textContent='■ Parar metrônomo';}
function changeBpm(value){bpm=Math.min(240,Math.max(30,Math.round(Number(value)||90)));$('#bpmvalue').textContent=bpm;$('#bpmrange').value=bpm;$('#bpmnumber').value=bpm;if(metroTimer)startMetro();}
const chords={C:{f:[-1,3,2,0,1,0],name:'Dó maior'},D:{f:[-1,-1,0,2,3,2],name:'Ré maior'},E:{f:[0,2,2,1,0,0],name:'Mi maior'},G:{f:[3,2,0,0,0,3],name:'Sol maior'},A:{f:[-1,0,2,2,2,0],name:'Lá maior'},Am:{f:[-1,0,2,2,1,0],name:'Lá menor'},Em:{f:[0,2,2,0,0,0],name:'Mi menor'},Dm:{f:[-1,-1,0,2,3,1],name:'Ré menor'}};
function chordSVG(f){return `<svg viewBox="0 0 150 175" role="img" aria-label="Cordas da mais grave à mais aguda; casas ${f.join(', ')}; menos um significa não tocar"><line x1="25" y1="40" x2="125" y2="40" stroke="#bbbbbb" stroke-width="4"/>${Array.from({length:5},(_,i)=>`<line x1="25" y1="${40+i*25}" x2="125" y2="${40+i*25}" stroke="#5f5f5f"/>`).join('')}${f.map((n,i)=>`<line x1="${25+i*20}" y1="40" x2="${25+i*20}" y2="140" stroke="#5f5f5f"/>${n>0?`<circle cx="${25+i*20}" cy="${40+(n-.5)*25}" r="8" fill="#ffffff"/>`:`<text x="${25+i*20}" y="24" text-anchor="middle" fill="#a7a7a7" font-size="13">${n===0?'○':'×'}</text>`}<text x="${25+i*20}" y="164" text-anchor="middle" fill="#929292" font-size="10">${['E','A','D','G','B','e'][i]}</text>`).join('')}</svg>`;}
function chordPage(){return head('CAIXA DE FERRAMENTAS','Novas formas de tocar.','Oito acordes essenciais para guitarra e violão em afinação padrão.')+`<div class="chordgrid">${Object.entries(chords).map(([key,c])=>`<section class="panel chord"><h2>${key}</h2><p>${c.name}</p>${chordSVG(c.f)}<button class="secondary" data-chord="${key}">♫ Ouvir acorde</button></section>`).join('')}</div><div class="hint">Leia o desenho de frente para o braço: corda mais grave à esquerda. ● = pressione a casa; ○ = corda solta; × = não toque. O som é sintetizado para servir como referência.</div>`;}
async function initAudio(){audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state!=='running')await audio.resume();}
async function playChord(key){try{await initAudio();const bases=[40,45,50,55,59,64];chords[key].f.forEach((f,i)=>{if(f<0)return;const t=audio.currentTime+i*.04,o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=440*2**((bases[i]+f-69)/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.07,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+1.6);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+1.7);});}catch{toast('O áudio não está disponível neste navegador.');}}
let sessionTimer=null,remaining=30*60,running=false;
function formatTime(s){return Math.floor(s/60).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0');}
function studies(){return head('MEUS ESTUDOS','Pequenos passos. Som grande.','Uma rotina simples para transformar vontade em prática.')+`<div class="metrolayout"><section class="panel"><div class="sectionhead"><h2>Sessão essencial</h2><span class="pill">30 minutos</span></div><p class="subtext">Aquecimento, técnica e repertório. Marque cada etapa ao concluir.</p>${sessionRows()}<div class="timer" id="sessiontime">${formatTime(remaining)}</div><div class="settings"><button class="primary wide" id="sessionplay">${running?'Ⅱ Pausar':'▶ Iniciar sessão'}</button><button class="secondary wide" id="finishsession">✓ Registrar prática</button></div><small style="text-align:center;margin-top:16px">Registre o tempo praticado; o cronômetro continua ao navegar pelo app.</small></section><section class="panel"><h2>Seu histórico</h2><p class="subtext" style="margin:10px 0 20px">A consistência aparece uma sessão por vez.</p>${history.length?history.slice().reverse().slice(0,7).map(h=>`<div class="sessionrow"><span class="toolicon">✓</span><div>Sessão de prática<small>${esc(h.date)}</small></div><span>${h.minutes} min</span></div>`).join(''):'<div class="hint">Seu primeiro registro vai aparecer aqui. Inicie o cronômetro e, ao terminar, clique em “Registrar prática”.</div>'}<button class="secondary wide" data-page="metronomo" style="margin-top:20px">Abrir metrônomo ↗</button></section></div>`;}
function ideaPage(){return head('TOCAR & CRIAR','A inspiração fica.','Riffs, letras e arranjos. Guarde a ideia enquanto ela está fresca.')+`<section class="panel"><form id="ideaform"><label>Título<input name="title" required maxlength="100" placeholder="Um nome para esta ideia"></label><label>Suas notas<textarea name="text" required rows="5" maxlength="10000" placeholder="Uma sequência de acordes, uma letra ou aquele riff…"></textarea></label><button class="primary" type="submit">+ Guardar ideia</button></form></section><div id="ideas">${ideas.map(i=>`<article class="ideacard"><div class="sectionhead"><h2>${esc(i.title)}</h2><small>${esc(i.date)}</small></div><p>${esc(i.text)}</p><button class="textbutton" data-convert="${esc(i.id)}">Adicionar ao repertório ↗</button></article>`).reverse().join('')||'<div class="hint">Seu caderno está pronto. Escreva sua primeira ideia acima.</div>'}</div>`;}
const names={inicio:'Visão geral',repertorio:'Meu repertório',estudos:'Meus estudos',metronomo:'Metrônomo',acordes:'Biblioteca de acordes',ideias:'Caderno de ideias',audio:'Tablaturas & áudio',recursos:'Todos os recursos'};
function render(next=page){if(next!==page&&page==='metronomo')stopMetro();if(next!==page&&page==='audio')AudioLab.stop();page=names[next]?next:'inicio';$('#main').innerHTML=({inicio:dashboard,repertorio:repertoire,estudos:studies,metronomo:metronome,acordes:chordPage,ideias:ideaPage,audio:AudioLab.page,recursos:resourcesPage}[page])();$('#crumb').textContent=names[page];$('#navcount').textContent=songs.length;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#sidebar').classList.remove('open');if(page==='metronomo'){ $('#meter').value=meter;$('#subdivision').value=subdivision;}historyReplace();if(page==='audio')AudioLab.mount();}
function historyReplace(){window.history.replaceState(null,'','#'+page);}
function showSong(id){const s=songs.find(x=>x.id===id);if(!s)return;$('#detaildialog').innerHTML=`<div class="dialoghead"><div><span class="eyebrow">${esc(s.artist||'MEU REPERTÓRIO')}</span><h2>${esc(s.title)}</h2></div><button class="iconbutton" data-close="detaildialog" aria-label="Fechar">✕</button></div><p class="subtext" style="margin-top:15px">Tom ${esc(s.key)} • ${esc(s.bpm)} BPM</p><label>Status<select id="songstatus" data-id="${esc(s.id)}">${['Estudando','Pronta','Ideia'].map(v=>`<option ${v===s.status?'selected':''}>${v}</option>`).join('')}</select></label><label>Cifras, tablatura ou anotações<textarea id="songnotes" rows="7">${esc(s.notes)}</textarea></label><div class="settings"><button class="primary" data-save-song="${esc(s.id)}">Salvar alterações</button><button class="secondary" data-practice="${s.bpm}">Praticar a ${s.bpm} BPM ↗</button></div>`;$('#detaildialog').showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.page){render(b.dataset.page);window.scrollTo(0,0);}if(b.hasAttribute('data-add'))$('#songdialog').showModal();if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.song)showSong(b.dataset.song);
if(b.dataset.check!==undefined){const key=today()+'-'+b.dataset.check;checked[key]=!checked[key];save();render();}
if(b.dataset.bpm)changeBpm(bpm+Number(b.dataset.bpm));if(b.id==='metroplay'){if(metroTimer)stopMetro();else try{await initAudio();startMetro();}catch{toast('O áudio não está disponível neste navegador.');}}
if(b.dataset.chord)playChord(b.dataset.chord);
if(b.dataset.saveSong){const s=songs.find(x=>x.id===b.dataset.saveSong);s.notes=$('#songnotes').value;s.status=$('#songstatus').value;save();$('#detaildialog').close();render();toast('Música atualizada.');}
if(b.dataset.practice){bpm=Number(b.dataset.practice);$('#detaildialog').close();render('metronomo');}
if(b.dataset.convert){const i=ideas.find(x=>x.id===b.dataset.convert);songs.push({id:crypto.randomUUID(),title:i.title,artist:'Minha composição',key:'Em',bpm:90,status:'Ideia',notes:i.text});save();render('repertorio');toast('Ideia adicionada ao repertório.');}
if(b.id==='mobilemenu')$('#sidebar').classList.toggle('open');if(b.id==='help'||b.id==='profile')toast('ënsaio v.03 • repertório, estudos, acordes e ideias. Dados neste navegador.');
if(b.id==='tap'){const now=performance.now();tapTimes.push(now);tapTimes=tapTimes.filter(t=>now-t<5000).slice(-6);if(tapTimes.length>1)changeBpm(60000/((now-tapTimes[0])/(tapTimes.length-1)));}
if(b.id==='sessionplay'){if(running){clearInterval(sessionTimer);running=false;}else{running=true;sessionTimer=setInterval(()=>{remaining=Math.max(0,remaining-1);if($('#sessiontime'))$('#sessiontime').textContent=formatTime(remaining);if(!remaining){clearInterval(sessionTimer);running=false;toast('30 minutos completos! Registre sua prática.');if(page==='estudos')render();}},1000);}render();}
if(b.id==='finishsession'){const elapsed=30*60-remaining;if(elapsed<60){toast('Pratique por pelo menos um minuto antes de registrar.');return;}history.push({date:today(),minutes:Math.floor(elapsed/60),timestamp:Date.now()});clearInterval(sessionTimer);running=false;remaining=30*60;save();render();toast('Prática registrada. Mais um passo na sua evolução!');}
});
let tapTimes=[];
document.addEventListener('input',e=>{if(e.target.id==='search'){filterSongs();}if(e.target.id==='bpmrange')changeBpm(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='filter')filterSongs();if(e.target.id==='bpmnumber')changeBpm(e.target.value);if(e.target.id==='meter'){meter=Number(e.target.value);$('#beats').innerHTML=Array.from({length:meter},(_,i)=>`<span class="beat" data-beat="${i}"></span>`).join('');if(metroTimer)startMetro();}if(e.target.id==='subdivision'){subdivision=Number(e.target.value);if(metroTimer)startMetro();}});
function filterSongs(){const term=$('#search').value.toLocaleLowerCase('pt-BR'),status=$('#filter').value;$('#results').innerHTML=songRows(songs.filter(s=>(s.title+' '+s.artist).toLocaleLowerCase('pt-BR').includes(term)&&(!status||s.status===status)));}
$('#songform').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);songs.unshift({id:crypto.randomUUID(),title:f.get('title').trim(),artist:f.get('artist').trim(),key:f.get('key'),bpm:Number(f.get('bpm')),status:f.get('status'),notes:f.get('notes')});save();e.target.reset();$('#songdialog').close();render();toast('Música adicionada ao repertório.');});
document.addEventListener('submit',e=>{if(e.target.id!=='ideaform')return;e.preventDefault();const f=new FormData(e.target);ideas.push({id:crypto.randomUUID(),title:f.get('title').trim(),text:f.get('text').trim(),date:today()});save();render();toast('Ideia guardada.');});
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));window.addEventListener('pagehide',()=>{stopMetro();clearInterval(sessionTimer);save();});
render(location.hash.slice(1)||'inicio');
